from produire import produire,paras,table,steps
from medicaments import nystatine
parts=[
('La candidose buccale est une infection muqueuse par des levures du genre Candida. Les {formes cliniques} dépassent le seul muguet à plaques blanches.',paras('Candida peut coloniser une bouche saine. La maladie exige une concordance entre lésions, symptômes et terrain ; un prélèvement positif isolé ne suffit pas.')),
('Le terrain et les expositions favorisent la prolifération. Les {facteurs de risque} doivent être recherchés à chaque récidive.',paras('Antibiotiques, corticoïdes inhalés, prothèses, sécheresse, diabète et immunodépression sont des contextes importants. L’âge ou une prothèse ne dispense pas de vérifier les autres causes d’une lésion persistante.')),
('La rupture de l’équilibre local permet une infection opportuniste. Les {mécanismes favorisants} expliquent l’intérêt de corriger la cause en plus du traitement.',paras('Baisse salivaire, modification de la flore et altération des défenses facilitent la prolifération. Une prothèse mal entretenue peut entretenir le réservoir et l’inflammation de la muqueuse couverte.')),
('Rechercher une atteinte au-delà de la bouche et un terrain vulnérable. Les {signes d’alarme} imposent une évaluation élargie.',paras('Odynophagie ou dysphagie, surtout en immunodépression, doivent faire rechercher une atteinte œsophagienne ou une autre infection. Déshydratation, sepsis ou fièvre sous neutropénie nécessitent une prise en charge urgente.')),
('L’entretien précise brûlure, goût, gêne alimentaire et traitements récents. Les {questions ciblées} recherchent facteurs persistants et mauvaise utilisation des soins.',paras('Demander modalités de corticoïdes inhalés, antibiotiques, hygiène des prothèses, sécheresse, diabète et facteurs d’immunodépression. Une récidive inexpliquée peut justifier un bilan orienté, y compris un dépistage du VIH avec information et consentement.')),
('Examiner toutes les muqueuses et retirer les prothèses. Les {aspects discriminants} orientent le diagnostic sans grattage agressif.',paras('La forme pseudomembraneuse présente des plaques blanchâtres détachables laissant une muqueuse inflammatoire. La forme érythémateuse peut être rouge et douloureuse sans dépôt ; la stomatite prothétique siège sous la prothèse. Une plaque non détachable nécessite un diagnostic différentiel et parfois une biopsie.')),
('Les lésions blanches ne sont pas toutes candidosiques. Le {diagnostic différentiel} protège contre des traitements répétés inadaptés.',table(['Aspect','À envisager'],[['Dépôt détachable avec inflammation.','Candidose pseudomembraneuse, selon contexte.'],['Stries ou plaques non détachables.','Lichen, leucoplasie, candidose hyperplasique ou autre lésion.'],['Ulcère focal induré.','Traumatisme ou tumeur à explorer.'],['Brûlure avec muqueuse peu modifiée.','Sécheresse ou autre cause ; ne pas conclure automatiquement à Candida.']])) ,
('Le diagnostic est souvent clinique devant une présentation typique. Les {critères de cohérence} relient la lésion au terrain.',paras('La présence de levures seule ne prouve pas leur rôle pathogène. Une réponse insuffisante doit faire revoir le diagnostic, l’administration, le réservoir prothétique et l’extension de l’infection.')),
('Les examens sont ciblés sur les situations atypiques ou réfractaires. Le {bilan complémentaire} peut rechercher l’espèce et un facteur sous-jacent.',paras('Prélèvement microbiologique si doute ou échec, puis sensibilité selon le contexte spécialisé. Bilan glycémique, immunitaire ou autre seulement si indiqué. Une plaque persistante non détachable peut nécessiter un avis de médecine buccale et une histologie.')),
('L’{algorithme pratique} distingue une atteinte locale simple d’une situation à risque. La correction des facteurs favorisants fait partie du traitement.',steps('Évaluer hydratation, déglutition et immunité.', 'Reconnaître la forme clinique et rechercher prothèse, sécheresse ou exposition médicamenteuse.', 'Choisir un antifongique compatible avec l’âge, la préparation et l’extension.', 'Réévaluer en cas de non-réponse ; ne pas multiplier les traitements empiriques sans revoir la cause.')),
('Une atteinte locale peut relever d’un antifongique buccal adapté. Les {modalités suisses} doivent être distinguées des schémas d’autres pays.',paras('La nystatine agit localement et ne traite pas une candidose systémique. Une atteinte œsophagienne suspectée ou une forme sévère en immunodépression impose une stratégie spécialisée.', '@@MEDICAMENTS@@')),
('Les {mesures de prévention} réduisent les réservoirs et les facteurs favorisants. Le soin de la muqueuse et celui de la prothèse sont complémentaires.',paras('Nettoyer la prothèse, l’entretenir selon les conseils dentaires et corriger son adaptation. Respecter les consignes de rinçage après corticoïde inhalé, limiter les irritants et traiter la sécheresse ou le déséquilibre glycémique identifiés.')),
('Une candidose peut être rouge sans plaque blanche. Une culture positive peut refléter une colonisation. Échec ou dysphagie imposent de revoir le diagnostic et l’extension. Les excipients peuvent limiter l’emploi d’une préparation malgré une ancienne indication.','')]
quiz=[('Candida peut-il être présent sans maladie ?','Oui : une colonisation est possible.'),('Le muguet blanc est-il la seule forme ?','Non : une forme érythémateuse peut dominer.'),('Les plaques du muguet sont-elles habituellement détachables ?','Oui, contrairement à plusieurs diagnostics différentiels.'),('Faut-il gratter fortement pour confirmer ?','Non : l’examen doit rester doux.'),('Une prothèse doit-elle être retirée pour examiner ?','Oui, pour voir la muqueuse couverte.'),('Un prélèvement positif suffit-il ?','Non : il faut une concordance clinique.'),('Que rechercher devant une odynophagie chez un immunodéprimé ?','Une atteinte œsophagienne ou une autre cause nécessitant une évaluation spécifique.'),('La nystatine traite-t-elle une candidose systémique ?','Non.'),('Quelle dose buccale figure dans la notice Mycostatine ?','1 ml à 100 000 unités internationales par ml, quatre fois par jour ; les conditions et restrictions restent à vérifier.'),('Quand la notice recommande-t-elle l’administration ?','À distance des repas, avec répartition dans la bouche si le patient le peut.'),('Combien de temps poursuivre après guérison clinique selon la notice ?','Au moins 48 heures.'),('La mention d’une prophylaxie néonatale suffit-elle pour utiliser la suspension chez un nouveau-né ?','Non : la rubrique des excipients interdit cette préparation avant quatre semaines.'),('Que vérifier lors de récidives ?','Terrain, sécheresse, médicaments, prothèse, diagnostic et modalités de traitement.'),('Une plaque non détachable persistante peut-elle recevoir des antifongiques indéfiniment ?','Non : un bilan spécialisé et parfois une biopsie sont nécessaires.')]
produire(3,parts,quiz,(1,2,14,17,23,24),nystatine)
